16: // Packed fp8e4m3fn -> fp16 conversion: converts 4 fp8 bytes in a uint32 to 4 fp16 values.
17: // Produces two uint32s in sequential half2 order: out_lo=[h1:h0], out_hi=[h3:h2].
18: // Ignores denormals (values with zero exponent map to small fp16 instead of zero).
19: __device__ __forceinline__ void fp8e4m3x4_to_half2x2(
20:     const uint32_t p, uint32_t& out_lo, uint32_t& out_hi)
21: {
22:     // p = [b3:b2:b1:b0], each byte is fp8e4m3fn.
23:     // Build byte pairs as [0:b1:0:b0] and [0:b3:0:b2] using V_PERM_B32.
24:     const uint32_t lo_pair = __builtin_amdgcn_perm(0u, p, 0x0c010c00u);
25:     const uint32_t hi_pair = __builtin_amdgcn_perm(0u, p, 0x0c030c02u);
26: 
27:     // For each 16-bit lane with byte x in [7:0]:
28:     // fp16 = (x << 7) + ((x & 0x80) << 7) + 0x2000
29:     // This form avoids explicit and_or masking and lowers to shift-add patterns.
30:     out_lo = (lo_pair << 7) + ((lo_pair & 0x00800080u) << 7) + 0x20002000u;
31:     out_hi = (hi_pair << 7) + ((hi_pair & 0x00800080u) << 7) + 0x20002000u;
32: }
33: 
34: // Packed fp8e5m2 -> fp16 conversion: converts 4 fp8 bytes in a uint32 to 4 fp16 values.
35: // Produces two uint32s in sequential half2 order: out_lo=[h1:h0], out_hi=[h3:h2].
36: // fp8e5m2: [sign:1][exp:5][mantissa:2], fp16: [sign:1][exp:5][mantissa:10]
37: // Exponent bias is 15 for both formats, so only mantissa needs zero-extension.
38: __device__ __forceinline__ void fp8e5m2x4_to_half2x2(
39:     const uint32_t p, uint32_t& out_lo, uint32_t& out_hi)
40: {
41:     // p = [b3:b2:b1:b0], each byte is fp8e5m2.
42:     // Build byte pairs as [b1:0:b0:0] and [b3:0:b2:0] using V_PERM_B32.
43:     out_lo = __builtin_amdgcn_perm(0u, p, 0x010c000cu);
44:     out_hi = __builtin_amdgcn_perm(0u, p, 0x030c020cu);
45: }
