406: torch::Tensor scaled_mm_prepacked(
407:     const torch::Tensor& a,
408:     const torch::Tensor& b_prepacked,
409:     const torch::Tensor& scale,
410:     const torch::Tensor& bias,
411:     const bool has_scale,
412:     const bool has_bias,
413:     const int64_t block_warps_m,
414:     const int64_t block_warps_n,
415:     const int64_t unroll_k,
416:     const int64_t stages,
417:     const int64_t repeat_m,
418:     const int64_t repeat_n,
419:     const int64_t b_dtype)
420: {
421:     TORCH_CHECK(a.is_cuda(), "a must be a CUDA tensor");
422:     TORCH_CHECK(b_prepacked.is_cuda(), "b_prepacked must be a CUDA tensor");
423:     TORCH_CHECK(a.scalar_type() == at::kHalf, "a must be float16");
424:     TORCH_CHECK(b_dtype == 0 || b_dtype == 1, "b_dtype must be 0 (fp8e4m3) or 1 (fp8e5m2)");
425:     TORCH_CHECK(a.dim() == 2, "a must be 2D");
426:     TORCH_CHECK(b_prepacked.dim() == 3, "b_prepacked must be 3D [K/16, N, 16]");
427: 
428:     const int64_t M = a.size(0);
429:     const int64_t K = a.size(1);
430:     const int64_t N = b_prepacked.size(1);
431:     TORCH_CHECK(K % kWmmaK == 0, "K must be divisible by 16");
432:     TORCH_CHECK(b_prepacked.size(0) == K / kWmmaK,
433:         "b_prepacked.shape[0] must equal K/16 (", K / kWmmaK, ")");
434:     TORCH_CHECK(b_prepacked.size(2) == kWmmaK, "b_prepacked.shape[2] must be 16");
