28: // Packed fp8e4m3fn → fp16 conversion: converts 4 fp8 bytes in a uint32 to 4 fp16 values.
29: // Produces two uint32s in sequential half2 order: out_lo=[h1:h0], out_hi=[h3:h2].
30: // Ignores denormals (values with zero exponent map to small fp16 instead of zero).
31: __device__ __forceinline__ void fp8x4_to_half2x2(
32:     const uint32_t p, uint32_t& out_lo, uint32_t& out_hi)
33: {
34:     // p = [b3:b2:b1:b0], each byte is fp8e4m3fn
35:     // Pair bytes for sequential output: [b1:b0] and [b3:b2]
36:     // lo_pair has b0 in [7:0] and b1 in [23:16]
37:     // hi_pair has b2 in [7:0] and b3 in [23:16]
38:     const uint32_t lo_pair = (p & 0xFFu) | ((p & 0xFF00u) << 8);       // [0:b1:0:b0]
39:     const uint32_t hi_pair = ((p >> 16) & 0xFFu) | ((p >> 8) & 0xFF0000u); // [0:b3:0:b2]
40: 
41:     // Convert each pair simultaneously using 32-bit ops:
42:     // For each byte x at [7:0] or [23:16]:
43:     //   fp16 = ((x & 0x80) << 8) | (((x & 0x7F) << 7) + 0x2000)
44:     {
45:         const uint32_t signs = (lo_pair & 0x00800080u) << 8;
46:         const uint32_t em = ((lo_pair & 0x007F007Fu) << 7) + 0x20002000u;
47:         out_lo = signs | em;  // [fp16(b1) : fp16(b0)]
48:     }
49:     {
50:         const uint32_t signs = (hi_pair & 0x00800080u) << 8;
51:         const uint32_t em = ((hi_pair & 0x007F007Fu) << 7) + 0x20002000u;
52:         out_hi = signs | em;  // [fp16(b3) : fp16(b2)]
53:     }
54: }
