73: 
74: template <int kBlockWarpsM,
75:           int kBlockWarpsN,
76:           int kUnrollK,
77:           int kStages,
78:           int kRepeatM,
79:           int kRepeatN>
80: __global__ void scaled_mm_kernel(
81:     const half* const a,
82:     const uint8_t* const b,
83:     const float* const scale,
84:     const half* const bias,
85:     half* const c,
