203:     const auto load_b_lds = [&](const int stage, const int64_t kk) -> void {
204:         // Load B with vec16 fp8→fp16 conversion, store to K×N layout
205:         #pragma unroll
206:         for (int v = 0; v < kBVecsPerThread; ++v) {
207:             const int vec_idx = tid + v * kThreads;
208:             const int elem_base = vec_idx * 16;
209:             if (elem_base >= kBElements) continue;
