230:     // =========================================================================
231:     // Split-phase load lambdas for VMEM/WMMA overlap (prefetch path)
232:     // Phase 1: issue global_load → VGPR buffers (VMEM unit, can overlap with WMMA)
233:     // Phase 2: VALU convert + ds_write from VGPR buffers → LDS (SIMD unit, serial)
234:     // =========================================================================
235: 
236:     // A prefetch buffers: one uint4 per vec load, per sub-iteration
237:     uint4 a_prefetch_buf[kUnrollK][kAVecsPerOwnerThread];
