267:         if constexpr (kUseWsgrAStoreOwnership) {
268:             if (wave_id >= kAOwnerWaves) return;
269:         }
270:         const int a_owner_tid = kUseWsgrAStoreOwnership ? (wave_id * kWaveSize + lane) : tid;
271: 
272:         #pragma unroll
273:         for (int v = 0; v < kAVecsPerOwnerThread; ++v) {
274:             const int vec_idx = a_owner_tid + v * kAOwnerThreads;
275:             if (vec_idx >= kAVecs) continue;
