292:             const int row = elem_base / kBlockN;
293:             const int col = elem_base % kBlockN;
294:             const int64_t b_row = kk + row;
295:             const int64_t b_col = block_n + col;
296: 
297:             const uint8_t* const b_ptr = b + b_row * stride_bk + b_col;
298:             const uint32_t* const p32 = reinterpret_cast<const uint32_t*>(b_ptr);
299:             #pragma unroll
300:             for (int j = 0; j < 4; ++j) {
301:                 b_prefetch_buf[u][v][j] = p32[j];
302:             }
303:         }
304:     };
305: 
306:     // Phase 2 for B: VALU fp8→fp16 convert + ds_write from VGPR buffer → LDS
307:     const auto commit_b_lds = [&](const int u, const int stage) -> void {
308:         #pragma unroll
309:         for (int v = 0; v < kBVecsPerThread; ++v) {
310:             const int vec_idx = tid + v * kThreads;
311:             const int elem_base = vec_idx * 16;
312:             if (elem_base >= kBElements) continue;
313: 
314:             const int row = elem_base / kBlockN;
315:             const int col = elem_base % kBlockN;
316: 
317:             uint32_t h32[8];
318:             #pragma unroll
319:             for (int j = 0; j < 4; ++j) {
320:                 fp8x4_to_half2x2(b_prefetch_buf[u][v][j], h32[2 * j], h32[2 * j + 1]);
321:             }
322:             uint4* const dst_ptr = reinterpret_cast<uint4*>(&sh_b[stage][row][col]);
323:             dst_ptr[0] = *reinterpret_cast<uint4*>(&h32[0]);
324:             dst_ptr[1] = *reinterpret_cast<uint4*>(&h32[4]);
325:         }
326:     };
327: 
328:     // Pipeline setup
329:     constexpr int kChunkK = kWmmaK * kUnrollK;
330:     const int total_chunks = static_cast<int>(K / kChunkK);
331: 
332:     const auto chunk_k0 = [&](const int iter_idx) -> int64_t {
333:         return static_cast<int64_t>(iter_idx) * kChunkK;
334:     };
335: 
336:     // True double-buffering requires kStages >= 2*kUnrollK (e.g. kStages=4, kUnrollK=2).
337:     // Read from stages [stage_base .. stage_base+kUnrollK-1],
338:     // write to stages [(stage_base+kUnrollK) .. (stage_base+2*kUnrollK-1)] % kStages.
339:     // Only 1 __syncthreads() per iteration since read/write stage sets are disjoint.
340:     constexpr bool kDoubleBuffer = (kStages >= 2 * kUnrollK);
341: 
342:     // WMMA compute lambda for one sub-iteration (one stage).
343:     // Register-tiling: load all B fragments once, then iterate rm with A loads.
344:     // Reduces LDS reads from (kRepeatM*kRepeatN)*(16+16) to kRepeatN*16 + kRepeatM*16.
345:     const auto wmma_compute_stage = [&](const int stage, const int64_t k0_iter) -> void {
346:         if (wave_id >= kBlockWarpsM * kBlockWarpsN) return;
347: 
348:         using fp16x16_t = _Float16 __attribute__((ext_vector_type(16)));
349:         using float8_t = float __attribute__((ext_vector_type(8)));
350: 
351:         const int lane_in_subgroup = lane % 16;
352: 
353:         // Pre-load all B fragments (one per rn tile)
354:         _Float16 all_reg_b[kRepeatN][16];
355:         #pragma unroll
356:         for (int rn = 0; rn < kRepeatN; ++rn) {
357:             const int tile_n = warp_n + rn * kBlockWarpsN;
358:             const int n_col = tile_n * kWmmaN + lane_in_subgroup;
359:             #pragma unroll
360:             for (int k = 0; k < kWmmaK; ++k) {
361:                 all_reg_b[rn][k] = static_cast<_Float16>(sh_b[stage][k][n_col]);
362:             }
363:         }
364: 
365:         // For each rm: load A once, compute all rn tiles with cached B
366:         #pragma unroll
367:         for (int rm = 0; rm < kRepeatM; ++rm) {
368:             const int tile_m = warp_m + rm * kBlockWarpsM;
369:             const int m_row = tile_m * kWmmaM + lane_in_subgroup;
370: 
371:             _Float16 reg_a_fp16[16];
372:             #pragma unroll
373:             for (int k0 = 0; k0 < kK0; ++k0) {
374:                 const half* const sh_a_src = sh_a_row_ptr(stage, k0, m_row);
375:                 #pragma unroll
376:                 for (int k1 = 0; k1 < kK1; ++k1) {
377:                     reg_a_fp16[k0 * kK1 + k1] = static_cast<_Float16>(sh_a_src[k1]);
378:                 }
379:             }
380: 
381:             const fp16x16_t a_frag = *reinterpret_cast<const fp16x16_t*>(reg_a_fp16);
382: 
383:             #pragma unroll
384:             for (int rn = 0; rn < kRepeatN; ++rn) {
385:                 const int repeat_idx = rm * kRepeatN + rn;
386:                 const fp16x16_t b_frag = *reinterpret_cast<const fp16x16_t*>(all_reg_b[rn]);
387:                 float8_t c_frag = *reinterpret_cast<float8_t*>(&acc[repeat_idx][0]);
388: 
389:                 c_frag = __builtin_amdgcn_wmma_f32_16x16x16_f16_w32(a_frag, b_frag, c_frag);
390: 
391:                 *reinterpret_cast<float8_t*>(&acc[repeat_idx][0]) = c_frag;
392:             }
393:         }
394:     };
395: 
396:     int stage_base = 0;
397: 
398:     // Prologue: load first chunk into LDS using monolithic loads
399:     #pragma unroll
400:     for (int u = 0; u < kUnrollK; ++u) {
401:         const int64_t k = static_cast<int64_t>(u) * kWmmaK;
402:         load_a_lds_k0mk1(u, k);
403:     }
404:     #pragma unroll
405:     for (int u = 0; u < kUnrollK; ++u) {
406:         const int64_t k = static_cast<int64_t>(u) * kWmmaK;
407:         load_b_lds(u, k);
408:     }
409:     __syncthreads();
410: 
411:     // =========================================================================
412:     // Main loop with VMEM/WMMA overlap via split-phase loads + ASM fences.
413:     //
414:     // When kDoubleBuffer (kStages >= 2*kUnrollK):
415:     //   Read stages [stage_base..+kUnrollK-1], write stages [stage_base+kUnrollK..+2*kUnrollK-1].
416:     //   Disjoint stage sets → no read/write race → only 1 __syncthreads().
417:     //
418:     // Schedule per iteration:
419:     //   1. prefetch_global(all u) for next chunk → VMEM (fire-and-forget)
420:     //   2. ASM fence
421:     //   3. WMMA compute(all u) on current stages → Matrix unit (CONCURRENT with VMEM)
422:     //   4. s_waitcnt vmcnt(0)
423:     //   5. commit_lds(all u) to next stages → VALU convert + ds_write
424:     //   6. __syncthreads() + advance stage_base
425:     //
426:     // When !kDoubleBuffer (kStages == kUnrollK):
427:     //   Fallback: serial compute-then-load with single __syncthreads().
428:     // =========================================================================
429:     for (int iter_idx = 0; iter_idx < total_chunks; ++iter_idx) {
430:         const int64_t k0_iter = chunk_k0(iter_idx);
431:         const bool has_next = (iter_idx + 1 < total_chunks);
432:         const int64_t k_next = has_next ? chunk_k0(iter_idx + 1) : 0;
433: 
434:         if constexpr (kDoubleBuffer) {
435:             // --- Phase 1: Issue global_load for next chunk (VMEM, fire-and-forget) ---
436:             if (has_next) {
437:                 #pragma unroll
438:                 for (int u = 0; u < kUnrollK; ++u) {
439:                     const int64_t k = k_next + static_cast<int64_t>(u) * kWmmaK;
440:                     prefetch_a_global(u, k);
441:                     prefetch_b_global(u, k);
442:                 }
443:             }
444: 
445:             // ASM fence: prevent compiler from moving WMMA before global_load
446:             asm volatile("" ::: "memory");
447: 
448:             // --- Phase 2: WMMA compute on current LDS data (Matrix unit) ---
449:             // Concurrent with in-flight global_loads on VMEM unit.
450:             #pragma unroll
451:             for (int u = 0; u < kUnrollK; ++u) {
452:                 const int read_stage = (stage_base + u) % kStages;
453:                 wmma_compute_stage(read_stage, k0_iter);
454:             }
455: 
456:             // --- Phase 3: Wait for global loads, then convert+store to NEXT stages ---
457:             // No barrier needed before commit — write stages are disjoint from read stages.
458:             if (has_next) {
459:                 asm volatile("s_waitcnt vmcnt(0)" ::: "memory");
460:                 #pragma unroll
461:                 for (int u = 0; u < kUnrollK; ++u) {
462:                     const int write_stage = (stage_base + kUnrollK + u) % kStages;
463:                     commit_a_lds(u, write_stage);
464:                     commit_b_lds(u, write_stage);
465:                 }
466:             }
467: 
468:             stage_base = (stage_base + kUnrollK) % kStages;
469:             __syncthreads();
470:         } else {
471:             // Fallback: serial compute-then-load (original schedule, 1 sync)
472:             #pragma unroll
473:             for (int u = 0; u < kUnrollK; ++u) {
474:                 const int stage = (stage_base + u) % kStages;
475:                 wmma_compute_stage(stage, k0_iter);
476:             }
477: 
478:             if (has_next) {
479:                 asm volatile("s_setprio 1" ::: "memory");
480:                 #pragma unroll
481:                 for (int u = 0; u < kUnrollK; ++u) {
482:                     const int stage = (stage_base + u) % kStages;
483:                     const int64_t k = k_next + static_cast<int64_t>(u) * kWmmaK;
484:                     load_a_lds_k0mk1(stage, k);
485:                 }
486:                 #pragma unroll
487:                 for (int u = 0; u < kUnrollK; ++u) {
488:                     const int stage = (stage_base + u) % kStages;
489:                     const int64_t k = k_next + static_cast<int64_t>(u) * kWmmaK;
490:                     load_b_lds(stage, k);
491:                 }
492:                 asm volatile("s_setprio 0" ::: "memory");
493:             }
494: 
495:             if constexpr (kStages != kUnrollK) {
496:                 stage_base = (stage_base + kUnrollK) % kStages;
497:             }
498:             __syncthreads();
499:         }
500:     }
501: 
502:     // Epilogue: C-Shuffle - write output with coalesced vec8 stores
503:     // Use LDS to transpose from column-major (WMMA layout) to row-major (coalesced)
504:     if (wave_id < kBlockWarpsM * kBlockWarpsN) {
505:         // Reuse sh_a memory for C-shuffle
506:         // Each warp gets its own 16×24 buffer (24 = 16 + 8 padding for bank conflicts)
507:         constexpr int kCPad = 8;
508:         constexpr int kCStride = kWmmaN + kCPad;  // 24 halfs per row
509:         half* const sh_c = sh_a + wave_id * kWmmaM * kCStride;
510: 
511:         const half scale_h = has_scale ? __float2half_rn(scale[0]) : __float2half_rn(1.0f);
512:         const int subgroup = lane / 16;
513:         const int lane_in_subgroup = lane % 16;
514: 
515:         #pragma unroll
516:         for (int rm = 0; rm < kRepeatM; ++rm) {
517:             #pragma unroll
518:             for (int rn = 0; rn < kRepeatN; ++rn) {
519:                 const int repeat_idx = rm * kRepeatN + rn;
520:                 const int tile_m = warp_m + rm * kBlockWarpsM;
521:                 const int tile_n = warp_n + rn * kBlockWarpsN;
522:                 const int64_t tile_m_base = block_m + tile_m * kWmmaM;
523:                 const int64_t tile_n_base = block_n + tile_n * kWmmaN;
524: 
525:                 // Step 1: Write acc to LDS in column-major order (WMMA layout)
526:                 // Each thread writes 8 values to one column
527:                 const int col = lane_in_subgroup;
528:                 #pragma unroll
529:                 for (int acc_idx = 0; acc_idx < 8; ++acc_idx) {
530:                     const int row_logical = subgroup * 8 + acc_idx;
531:                     const int row_phys = a_row_logical_to_phys_16(row_logical);
532:                     half val = __float2half_rn(acc[repeat_idx][acc_idx]);
533:                     val = __hmul(val, scale_h);
534:                     sh_c[row_phys * kCStride + col] = val;
535:                 }
536: 
537:                 // Wave executes in lockstep (SIMT), so all writes complete before reads
538:                 // No explicit barrier needed within a wave
539: 
540:                 // Step 2: Read from LDS in row-major order for coalesced global write
541:                 // 32 threads -> 16 rows, 2 threads per row, each handles 8 columns
542:                 const int read_row = lane / 2;
543:                 const int read_row_phys = a_row_logical_to_phys_16(read_row);
544:                 const int col_half = lane % 2;  // 0 = cols 0-7, 1 = cols 8-15
545:                 const int read_col_base = col_half * 8;
546: 
547:                 const int64_t out_row = tile_m_base + read_row;
548:                 const int64_t out_col = tile_n_base + read_col_base;
549: 
550:                 half* const out_ptr = c + out_row * stride_cm + out_col;
551:                 half* const h = sh_c + read_row_phys * kCStride + read_col_base;
