568: // Config tag for kernel (no vec_a/vec_b params - always uses vec8 A, vec16 B)
569: template <int M, int N, int U, int STAGES, int RM, int RN>
570: struct ConfigTag {
571:     static constexpr int kBlockWarpsM = M;
572:     static constexpr int kBlockWarpsN = N;
573:     static constexpr int kUnrollK = U;
574:     static constexpr int kStages = STAGES;
