579: torch::Tensor scaled_mm(
580:     const torch::Tensor& a,
581:     const torch::Tensor& b,
582:     const torch::Tensor& scale,
583:     const torch::Tensor& bias,
584:     const bool has_scale,
585:     const bool has_bias,
586:     const int64_t block_warps_m,
587:     const int64_t block_warps_n,
588:     const int64_t unroll_k,
589:     const int64_t stages,
590:     const int64_t repeat_m,
591:     const int64_t repeat_n)
592: {
593:     TORCH_CHECK(a.is_cuda(), "a must be a CUDA tensor");
594:     TORCH_CHECK(b.is_cuda(), "b must be a CUDA tensor");
595:     TORCH_CHECK(a.scalar_type() == at::kHalf, "a must be float16");
596:     TORCH_CHECK(b.scalar_type() == c10::ScalarType::Float8_e4m3fn, "b must be float8_e4m3fn");
597:     TORCH_CHECK(a.dim() == 2 && b.dim() == 2, "a and b must be 2D");
598:     TORCH_CHECK(a.size(1) == b.size(0), "a and b shapes are incompatible");
599:     TORCH_CHECK(bias.scalar_type() == at::kHalf || !has_bias, "bias must be float16");
600: 
601:     // Contiguous fast path requirements
602:     TORCH_CHECK(a.stride(1) == 1, "a must be row-contiguous (stride(1) == 1)");
603:     TORCH_CHECK(b.stride(1) == 1, "b must be row-contiguous (stride(1) == 1)");
604: 
605:     if (has_scale) {
606:         TORCH_CHECK(scale.is_cuda(), "scale must be a CUDA tensor");
607:         TORCH_CHECK(scale.numel() == 1, "scale must have one element");
608:         TORCH_CHECK(scale.scalar_type() == at::kFloat, "scale must be float32");
609:     }
610:     if (has_bias) {
611:         TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
612:         TORCH_CHECK(bias.numel() == b.size(1), "bias must have N elements");
613:         TORCH_CHECK(bias.scalar_type() == at::kHalf, "bias must be float16");
614:     }
615: 
616:     auto c = torch::empty({a.size(0), b.size(1)}, a.options().dtype(at::kHalf));
617: 
618:     const half* const a_ptr = reinterpret_cast<const half*>(a.data_ptr<at::Half>());
619:     const uint8_t* const b_ptr = reinterpret_cast<const uint8_t*>(b.data_ptr());
620:     auto stream = at::cuda::getCurrentCUDAStream();
621:     const float* const scale_ptr = has_scale ? scale.data_ptr<float>() : nullptr;
622:     const half* const bias_ptr = has_bias ? reinterpret_cast<const half*>(bias.data_ptr<at::Half>()) : nullptr;
623:     half* const c_ptr = reinterpret_cast<half*>(c.data_ptr<at::Half>());
624: 
625:     const auto is_aligned_16 = [](const void* const p) {
626:         return (reinterpret_cast<uintptr_t>(p) & 0xFu) == 0u;
627:     };
628:     TORCH_CHECK(is_aligned_16(a_ptr), "a data pointer must be 16-byte aligned");
629:     TORCH_CHECK(is_aligned_16(b_ptr), "b data pointer must be 16-byte aligned");
630:     TORCH_CHECK(is_aligned_16(c_ptr), "c data pointer must be 16-byte aligned");
631: 
632:     const auto launch = [&](const auto tag) -> void {
633:         constexpr int kBlockWarpsM = decltype(tag)::kBlockWarpsM;
634:         constexpr int kBlockWarpsN = decltype(tag)::kBlockWarpsN;
635:         constexpr int kUnrollK = decltype(tag)::kUnrollK;
636:         constexpr int kStages = decltype(tag)::kStages;
637:         constexpr int kRepeatM = decltype(tag)::kRepeatM;
638:         constexpr int kRepeatN = decltype(tag)::kRepeatN;
639:         constexpr int kBlockM = kWmmaM * kBlockWarpsM * kRepeatM;
640:         constexpr int kBlockN = kWmmaN * kBlockWarpsN * kRepeatN;
641: 
642:         TORCH_CHECK(a.size(0) % kBlockM == 0,
643:             "M (", a.size(0), ") must be divisible by kBlockM (", kBlockM, ")");
644:         TORCH_CHECK(b.size(1) % kBlockN == 0,
645:             "N (", b.size(1), ") must be divisible by kBlockN (", kBlockN, ")");
646:         TORCH_CHECK(a.size(1) % (kWmmaK * kUnrollK) == 0,
647:             "K (", a.size(1), ") must be divisible by kChunkK (", kWmmaK * kUnrollK, ")");
648: 
649:         constexpr int kThreadsPerBlock = kWaveSize * kBlockWarpsM * kBlockWarpsN;
650:         static_assert(kThreadsPerBlock <= 1024, "Block size exceeds HIP thread-per-block limit");
651:         const dim3 block(kThreadsPerBlock, 1, 1);
652:         const dim3 grid(
653:             static_cast<uint32_t>(b.size(1)) / kBlockN,
654:             static_cast<uint32_t>(a.size(0)) / kBlockM);
655: 
656:         hipLaunchKernelGGL(
657:             (scaled_mm_kernel<kBlockWarpsM, kBlockWarpsN, kUnrollK, kStages, kRepeatM, kRepeatN>),
658:             grid, block, 0, stream.stream(),
659:             a_ptr, b_ptr, scale_ptr, bias_ptr, c_ptr,
660:             a.size(0), b.size(1), a.size(1),
661:             a.stride(0), b.stride(0), c.stride(0),
662:             has_scale ? 1 : 0, has_bias ? 1 : 0);
663:     };
664: 
665:     const auto try_launch = [&](const auto tag) -> bool {
666:         if (block_warps_m == decltype(tag)::kBlockWarpsM &&
667:             block_warps_n == decltype(tag)::kBlockWarpsN &&
668:             unroll_k == decltype(tag)::kUnrollK &&
669:             stages == decltype(tag)::kStages &&
670:             repeat_m == decltype(tag)::kRepeatM &&
671:             repeat_n == decltype(tag)::kRepeatN) {
672:             launch(tag);
673:             return true;
674:         }
675:         return false;
676:     };
677: 
678:     // Autotune candidate configs (kept in sync with kernel/hip/hip_kernel.py::_CONFIGS).
679:     // Format: (warps_m, warps_n, unroll_k, stages, repeat_m, repeat_n)
680:     const bool launched =
681:         try_launch(ConfigTag<2, 2, 2, 2, 4, 4>{}) ||
682:         try_launch(ConfigTag<2, 4, 2, 2, 4, 2>{}) ||
683:         try_launch(ConfigTag<2, 4, 2, 2, 4, 4>{}) ||
684:         try_launch(ConfigTag<4, 2, 2, 2, 2, 4>{}) ||
685:         false;
686: 
687:     TORCH_CHECK(launched, "Unsupported config");
688:     return c;
689: }
