}

Tensor qk_int8_sv_f16_accum_f16_attn_inst_buf(Tensor query,
                    Tensor key,
                    Tensor value,
                    Tensor output,
                    Tensor query_scale,
                    Tensor key_scale,
                    int64_t tensor_layout,
