\documentclass[a4paper]{ctexart}
\usepackage{algorithm}
\usepackage{algpseudocode}
\usepackage{amsmath}
\usepackage{enumitem}
\usepackage{float}
\usepackage[bottom]{footmisc}
\usepackage{fullpage}
\usepackage{graphicx}
\usepackage{hyperref}
\usepackage{subcaption}

\floatname{algorithm}{算法}

\title{基于极大空矩形与正交可视图的模块连线避障算法}
\author{吴典}
\date{2025年9月14日}

\begin{document}

\maketitle

\begin{abstract}
TODO
\end{abstract}

\section{问题的直观描述}

考虑一块二维画布，其上放有多个矩形模块。模块之间有一些路径相连，每条路径由一些线段组成。所有模块边缘和线段只能沿水平或竖直方向。画布尺寸、模块的位置和尺寸、路径上各个拐点的位置都用浮点数表示。

现在给定一对起点与终点，求它们之间的一条路径。直观而言，这条路径需要满足以下要求：
\begin{enumerate}[noitemsep]
\item 路径不能穿过任何模块；
\item 长度尽量短；
\item 拐点尽量少；
\item 尽量不与其他路径重叠；
\item 尽量穿过障碍物（包括模块、其他路径）的正中间。
\end{enumerate}

这一问题不仅是各类流程图绘制、图形化编程软件的必备功能，也在集成电路设计、城市道路规划等领域有所应用。

\section{优化目标与约束条件的严格定义}

\subsection{模块周围的余量}

\begin{figure}[h]
\centering
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth, trim={1cm 2.8cm 1cm 2cm}, clip]{fig/ex_avoid_bad.pdf}
\caption{}
\end{subfigure}
\hfill
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth, trim={1cm 2.8cm 1cm 2cm}, clip]{fig/ex_avoid_good.pdf}
\caption{}
\end{subfigure}
\caption{路径与模块之间留出余量的效果。灰色矩形为模块，黑色折线为路径，橙色圆点为所求路径起点，绿色方形点则为终点。(a) 没有留出余量；(b) 红色区域为余量。}
\label{fig:margin}
\end{figure}

首先考虑“路径不能穿过任何模块”这一条件。当路径绕过模块时，如果严格遵守这一条件，同时令路径长度尽量短，则路径会贴在模块边缘，并不美观，如图~\ref{fig:margin}~(a)。更加美观的做法是在模块周围留出一定的“余量”长度，规定路径与模块的距离不能小于这一余量，如图~\ref{fig:margin}~(b)。合适的余量长度与画布尺寸、模块尺寸等因素有关，在测试用例中我们不妨设为10。同时，我们假设给定的模块互不重叠\footnote{模块相互重叠确实是用户操作制图软件时经常发生的情况，但这会导致“所求路径的起点或终点在另一模块内部”等更多特殊情况，因此本项目暂不考虑。}。

\subsection{拐点惩罚系数}

\begin{figure}[h]
\centering
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth, trim={1cm 0cm 1cm 0cm}, clip]{fig/ex_bend.pdf}
\caption{}
\end{subfigure}
\hfill
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth, trim={1cm 0cm 1cm 0cm}, clip]{fig/ex_bend_2.pdf}
\caption{}
\end{subfigure}
\caption{路径长度与拐点数量的取舍。}
\label{fig:bend}
\end{figure}

其次考虑“路径长度尽量短”与“拐点尽量少”的取舍。在图~\ref{fig:bend} 所示的模块布局中，(a)是一条长度较短，但拐点较多的路径，(b)则相反。如果图中的障碍物很高，导致一次性绕过两个障碍物所需的路径长度很长，那么我们倾向于选择(a)，反之则倾向于(b)。因此我们定义一个“拐点惩罚系数”$c_\text{拐} > 0$，并将优化目标写作路径长度与拐点数量的线性组合：
\begin{equation}
L(S) = \int_S \mathrm{d}s + c_\text{拐} n_\text{拐}
\label{eq:target-bend}
\end{equation}
其中$L(S)$为优化目标，它是所求路径$S$的函数，$\int_S \mathrm{d}s$为沿路径的长度积分，$n_\text{拐}$为拐点数量。在测试用例中我们不妨设$c_\text{拐} = 100$。

\subsection{路径周围的余量与路径重叠惩罚系数}

\begin{figure}[h]
\centering
\includegraphics[width=0.5\textwidth, trim={1cm 2.5cm 1cm 2cm}, clip]{fig/ex_path_margin.pdf}
\caption{路径周围留出余量的效果。画布上已有一条路径，红色区域为其周围的余量，橙色圆点与绿色方形点之间为现在所求的路径。为展示路径不重叠的效果，此图忽略拐点数量的限制。}
\label{fig:path-margin}
\end{figure}

接下来考虑“尽量不与其他路径重叠”。如果严格判断两条平行线段是否重叠，容易遇到浮点误差的问题。即使在两条线段之间留出一个浮点误差的距离，在视觉上也无法区分，并不美观。按照与图~\ref{fig:margin}~(b)相同的思路，我们在每条线段周围留出一圈余量，即将每个线段转换为一个矩形，如图~\ref{fig:path-margin}。

然而这一条件与上述的条件之间也需要取舍。在图~\ref{fig:path-margin}中，如果严格要求拐点数量尽量少，则新增的路径将是一条直线段，与已有的路径重叠。因此我们定义一个“路径重叠惩罚系数”$c_\text{叠} > 1$，并将优化目标写作：
\begin{equation}
L(S) = \int_S f_\text{叠}(x, y)\,\mathrm{d}s + c_\text{拐} n_\text{拐}
\label{eq:target-path-margin}
\end{equation}
若当前坐标$(x, y)$在任一现有路径的余量矩形内，则函数$f_\text{叠}(x, y) = c_\text{叠}$，否则为$1$。这样一来，我们倾向于使所求路径不与现有路径的余量矩形重叠，同时考虑上述的长度和拐点数量目标。在测试用例中我们不妨设$c_\text{叠} = 2$。

\subsection{极大空矩形、中线与路径居中奖励系数}

\begin{figure}[h]
\centering
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth, trim={1cm 0cm 1cm 0cm}, clip]{fig/ex_middle.pdf}
\caption{}
\end{subfigure}
\hfill
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth, trim={1cm 0cm 1cm 0cm}, clip]{fig/ex_middle_2.pdf}
\caption{}
\end{subfigure}
\caption{路径居中的效果。}
\label{fig:middle}
\end{figure}

最后考虑“尽量穿过障碍物的正中间”。在一些简单情况下我们可以对“正中间”作出直观的定义，如图~\ref{fig:middle}~(a)，路径应该穿过模块C与D正中间的y坐标，以及A与C、B与C正中间的x坐标。然而，在图~\ref{fig:middle}~(b)的模块布局中，C与D、E与F的正中间坐标并不相同。此时路径应该穿过C与D的正中间，还是E与F的正中间，又或者以增加两个拐点为代价，分别穿过两个正中间？

\begin{figure}[h]
\centering
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth]{fig/max_empty_rect.pdf}
\caption{}
\end{subfigure}
\hfill
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth]{fig/max_empty_rect_2.pdf}
\caption{}
\end{subfigure}
\caption{极大空矩形的例子。(a) 图中共有9个极大空矩形，每个橙色、绿色、蓝色边框都是一个极大空矩形，为了显示清楚而对边框位置略有调整。(b) 只考虑两个障碍物之间的极大空矩形，则剩下2个。虚线为极大空矩形的中线，路径倾向于穿过这些中线。}
\label{fig:max-empty-rect}
\end{figure}

为了在任何障碍物布局中，严格定义所有空白区域的“正中间”，我们考虑“极大空矩形”（maximum empty rectangle）~\cite{naamad1984maximum}的概念。如果一个矩形位于空白区域中，并且不存在更大的矩形将其完全包含且位于空白区域中，则我们定义它为极大空矩形。可以推论，一个极大空矩形的每条边一定与某一障碍物或画布的某一边界邻接。如图~\ref{fig:max-empty-rect}~(a)，图中共有9个极大空矩形。在求解路径时，我们只考虑两个障碍物之间的极大空矩形，而不考虑障碍物与画布边界之间的极大空矩形。也就是说，该矩形必须有相对的两边与障碍物邻接。如图~\ref{fig:max-empty-rect}~(b)，剩下2个极大空矩形。

若一个极大空矩形的左右两边与障碍物邻接，我们取一条竖直线段，其x坐标为该矩形的左右坐标平均值，y坐标范围为该矩形的上下坐标，将其定义为“竖直中线”。同理可定义“水平中线”。图~\ref{fig:max-empty-rect}~(b)中的虚线就是中线，路径倾向于穿过这些中线。按照与公式~(\ref{eq:target-path-margin})相同的思路，我们定义一个“路径居中奖励系数”$c_\text{中} \in (0, 1)$，并将优化目标写作：
\begin{equation}
L(S) = \int_S f_\text{叠}(x, y) f_\text{中}(x, y)\,\mathrm{d}s + c_\text{拐} n_\text{拐}
\label{eq:target}
\end{equation}
若当前坐标$(x, y)$在任一中线上，则函数$f_\text{中}(x, y) = c_\text{中}$，否则为$1$。在测试用例中我们不妨设$c_\text{中} = 0.9$。

\begin{figure}[h]
\centering
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth, trim={1cm 2cm 1cm 0cm}, clip]{fig/out3.pdf}
\caption{}
\end{subfigure}
\hfill
\begin{subfigure}[b]{0.49\textwidth}
\includegraphics[width=\textwidth, trim={1cm 2cm 1cm 0cm}, clip]{fig/out3_middle.pdf}
\caption{}
\end{subfigure}
\caption{路径长度与路径居中的取舍。(a) $c_\text{中} = 0.9$；(b) $c_\text{中} = 0.6$。}
\label{fig:len-vs-middle}
\end{figure}

这一条件与上述的条件之间同样需要取舍。如图~\ref{fig:len-vs-middle}，当$c_\text{中}$减小到$0.6$时，路径以增加一些长度为代价，故意穿过上方几个模块之间的中线。直观而言我们认为路径居中这一条件的优先级低于上述的所有条件，因此$c_\text{中}$应该取接近$1$的值。

接下来我们需要求出路径$S$，使得公式~(\ref{eq:target})这一优化目标达到最小值。

\section{算法分析}

\subsection{极大空矩形}

在求解路径之前，我们首先需要求出所有的极大空矩形。文献~\cite{naamad1984maximum}提出了一种基于扫描线的算法，见算法~\ref{alg:max-empty-rect}。

\begin{algorithm}[h]
\caption{求所有极大空矩形。}
\label{alg:max-empty-rect}
\begin{algorithmic}[1]
\State 输入障碍物矩形的集合\texttt{inRects}
\State 输出矩形的集合记作\texttt{outRects}，初始化为空集
\State 统计所有矩形上边缘与下边缘的坐标，记作数组\texttt{ys}，排序并去重
\For{\texttt{t} $\in$ \texttt{ys}}
    \State 对\texttt{inRects}中所有下边缘为\texttt{t}的矩形，将其x坐标范围合并为区间集合$\mathcal{T}$
    \State \algorithmicif\ $\mathcal{T}$为空\ \algorithmicthen\ \textbf{continue}
    \State 定义区间集合$\mathcal{X}$，初始化为整个画布的水平区间
    \For{\texttt{b} $\in$ \texttt{ys}}
        \State 对\texttt{inRects}中所有上边缘为\texttt{b}且下边缘$>$ \texttt{t}的矩形，将其x坐标范围合并为$\mathcal{B}$
        \State \algorithmicif\ $\mathcal{B}$为空\ \algorithmicthen\ \textbf{continue}
        \If{\texttt{t} < \texttt{b}}
            \For{区间\texttt{X} $\in \mathcal{X}$}
                \If{\texttt{X}与$\mathcal{B}$中的任一区间有交集}
                    \State 将\texttt{X}，\texttt{t}，\texttt{b}定义的矩形放入\texttt{outRects}
                \EndIf
            \EndFor
        \EndIf
        \State $\mathcal{X} \gets \mathcal{X} - \mathcal{B}$，此时$\mathcal{X}$被切割成更多区间
        \State $\mathcal{X} \gets \{\text{\texttt{X}} \mid \text{\texttt{X}} \in \mathcal{X}\ \text{且\texttt{X}与$\mathcal{T}$中的任一区间有交集}\}$
    \EndFor
\EndFor
\end{algorithmic}
\end{algorithm}

在最坏情况下，该算法的时间复杂度为$O(n_\text{障}^3)$，其中$n_\text{障}$为障碍物的数量，因为有三层循环，每一层的计算量都是$O(n_\text{障})$。空间复杂度为$O(n_\text{障}^2)$，由输出极大空矩形的数量$n_\text{空}$决定，$n_\text{空} = O(n_\text{障}^2)$，即每个障碍物的下边缘与其下方每个障碍物的上边缘之间都可以有一个极大空矩形。

不过，该算法在具体问题上的时间和空间消耗很大程度上取决于障碍物的布局，随机情况下的复杂度优于最坏情况。通过数值模拟我们发现，对随机放置的障碍物，极大空矩形的数量可以拟合为$n_\text{空} = O(n_\text{障}^{1 + \alpha})$，其中$\alpha \approx 0.2$，如图~\ref{fig:rand-counts}。

\begin{figure}[h]
\centering
\includegraphics[width=0.5\textwidth]{fig/rand_counts.pdf}
\caption{极大空矩形数量$n_\text{空}$与障碍物矩形数量$n_\text{障}$的关系。}
\label{fig:rand-counts}
\end{figure}

在上述的定义中$n_\text{障} = n_\text{模块} + n_\text{线段}$，其中$n_\text{模块}$为模块数量，$n_\text{线段}$为已有路径的线段数量之和。而求解路径时所有要考虑的物体，包括极大空矩形中线、障碍物、所求路径起点与终点，按随机情况考虑，其总数为$N = n_\text{空} + n_\text{障} + 2 = O(n_\text{空}) = O(n_\text{障}^{1 + \alpha})$。

\subsection{正交可视图}

虽然公式~(\ref{eq:target})用一个积分表示路径长度，但事实上路径的拐点只能出现在障碍物边缘、中线等特殊位置。因此我们把连续的坐标离散化，再把离散坐标之间的连通关系转换为一个图结构。根据公式~(\ref{eq:target})计算图上各条边的权重。这一图结构在文献~\cite{wybrow2009orthogonal}中称为“正交可视图”（orthogonal visibility graph），构造它的过程见算法~\ref{alg:graph}。

\begin{algorithm}[h]
\caption{构造正交可视图。为简洁起见，省略一些边界条件的处理。}
\label{alg:graph}
\begin{algorithmic}[1]
\State 输入模块的集合$\mathcal{C}$，线段余量矩形的集合$\mathcal{L}$，中线的集合$\mathcal{M}$，所求路径起点\texttt{s}，终点\texttt{e}
\State 输出正交可视图中边的集合$\mathcal{E}$
\State 统计$\mathcal{C}$，$\mathcal{L}$，$\mathcal{M}$，\texttt{s}，\texttt{e}中所有物体左右边缘的坐标，记作数组\texttt{xs}，排序并去重
\State 统计其上下边缘的坐标，记作数组\texttt{ys}，排序并去重
\State 记\texttt{xs}的长度为\texttt{I}，\texttt{ys}的长度为\texttt{J}，定义二维数组\texttt{h}，\texttt{v}，大小为\texttt{I*J}
\For{\texttt{i} $\in$ \texttt{[0, I)}，\texttt{j} $\in$ \texttt{[0, J)}}
    \State \texttt{h[i, j]} $\gets$ \texttt{xs[i+1] - xs[i]}，\texttt{v[i, j]} $\gets$ \texttt{ys[j+1] - ys[j]}
\EndFor
\For{模块\texttt{C} $\in \mathcal{C}$} \Comment{根据公式~(\ref{eq:target})计算图上各条边的权重}
    \For{坐标\texttt{(i, j)} $\in$ \texttt{C}}
        \State \texttt{h[i, j]} $\gets \infty$，\texttt{v[i, j]} $\gets \infty$
    \EndFor
\EndFor
\For{线段余量矩形\texttt{L} $\in \mathcal{L}$}
    \For{坐标\texttt{(i, j)} $\in$ \texttt{L}}
        \State \texttt{h[i, j] *=} \,$c_\text{叠}$，\texttt{v[i, j] *=} \,$c_\text{叠}$
    \EndFor
\EndFor
\For{中线\texttt{M} $\in \mathcal{M}$}
    \For{坐标\texttt{(i, j)} $\in$ \texttt{M}}
        \State \texttt{h[i, j] *=} \,$c_\text{中}$，\texttt{v[i, j] *=} \,$c_\text{中}$
    \EndFor
\EndFor
\For{\texttt{i} $\in$ \texttt{[0, I)}，\texttt{j} $\in$ \texttt{[0, J)}}
    \State 将连接顶点\texttt{(i, j)}与\texttt{(i+1, j)}，权重为\texttt{h[i, j]}的边放入$\mathcal{E}$
    \State 将连接顶点\texttt{(i, j)}与\texttt{(i, j+1)}，权重为\texttt{v[i, j]}的边放入$\mathcal{E}$
\EndFor
\end{algorithmic}
\end{algorithm}

在最坏情况与随机情况下，该算法的时间和空间复杂度都是$O(N^2)$。对所有物体进行统计后，x与y坐标的数量都是$O(N)$。正交可视图中的所有顶点就是这些x与y坐标的直积，数量为$|\mathcal{V}| = O(N^2)$，如图~\ref{fig:graph-nodes} 所示。每个顶点周围最多可能有$4$条边，因此所有边的数量$|\mathcal{E}| = O(N^2)$。

\begin{figure}[h]
\centering
\includegraphics[width=0.5\textwidth, trim={1cm 2.5cm 1cm 2cm}, clip]{fig/graph_nodes.pdf}
\caption{正交可视图顶点的例子。蓝色圆点为正交可视图的顶点，其坐标来自所有矩形、中线、以及所求路径起点与终点的x与y坐标的直积。所求路径的拐点只可能为这些点。在没有模块阻挡时，它们与上下左右的顶点有边连通。为简明起见，此图忽略矩形周围的余量。}
\label{fig:graph-nodes}
\end{figure}

\subsection{最短路径}

构造出正交可视图之后，我们便能用成熟的最短路径算法求出从给定起点到终点、权重之和最小的路径。本项目使用A$^*$搜索算法~\cite{hart1968formal}，在最坏情况下，它的时间复杂度为$O(|\mathcal{E}| + |\mathcal{V}| \log |\mathcal{V}|) = O(N^2 \log N)$，空间复杂度为$O(|\mathcal{V}|) = O(N^2)$。而在随机情况下，A$^*$搜索算法的效率很大程度上取决于启发函数。由于平面上的曼哈顿距离对我们的寻路问题是相当好的启发函数，其时间和空间复杂度往往可以达到$O(|\mathcal{V}|^{\frac{1}{2}}) = O(N)$。

