#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#include "routenodes.h"
#include "third_party/nlohmann/json.hpp"

using json = nlohmann::json;

// Helper function to parse a string like "x,y" into a CustomPoint
CustomPoint parsePoint(const std::string& s)
{
    std::stringstream ss(s);
    std::string item;
    float x, y;
    std::getline(ss, item, ',');
    x = std::stof(item);
    std::getline(ss, item, ',');
    y = std::stof(item);
    return {x, y};
}

// JSON serialization/deserialization for CustomPoint
void to_json(json& j, const CustomPoint& p)
{
    j = json{{"x", p.x}, {"y", p.y}, {"direction", p.direction}};
}

void from_json(const json& j, CustomPoint& p)
{
    if (j.is_string())
    {
        p = parsePoint(j.get<std::string>());
    }
    else
    {
        j.at("x").get_to(p.x);
        j.at("y").get_to(p.y);
        j.at("direction").get_to(p.direction);
    }
}

// JSON serialization/deserialization for CompPartInfo
void to_json(json& j, const CompPartInfo& c)
{
    j = json{{"width", c.width}, {"height", c.height}, {"pos", c.pos}};
}

void from_json(const json& j, CompPartInfo& c)
{
    j.at("Width").get_to(c.width);
    j.at("Height").get_to(c.height);
    c.pos = parsePoint(j.at("Position").get<std::string>());
}

// JSON serialization/deserialization for Path
void to_json(json& j, const Path& p)
{
    j = json::array();
    for (const auto& point : p)
    {
        j.push_back(point);
    }
}

void from_json(const json& j, Path& p)
{
    for (const auto& item : j)
    {
        p.push_back(parsePoint(item.get<std::string>()));
    }
}

// JSON serialization/deserialization for CompAndCanvasInfo
void to_json(json& j, const CompAndCanvasInfo& c)
{
    j = json{{"graphicSceneWidth", c.graphicSceneWidth},
             {"graphicSceneHeight", c.graphicSceneHeight},
             {"compPartInfos", c.compPartInfos},
             {"paths", c.paths},
             {"startNode", c.startNode},
