#include "routenodes.hpp"
#include "third_party/nlohmann/json.hpp"

using json = nlohmann::ordered_json;

namespace routenodes
{

// CustomPoint序列化
void to_json(json& j, const CustomPoint& p)
{
    std::ostringstream ss;
    ss << p.x << "," << p.y;
    j = ss.str();
}

void from_json(const json& j, CustomPoint& p)
{
    if (j.is_string())
    {
        // 解析"x,y"
        float x, y;
        char comma;
        std::istringstream ss(j.get<std::string>());
        ss >> x >> comma >> y;
        p.x = x;
        p.y = y;
    }
    else
    {
        // 不但读取x y，也读取direction
        j.at("x").get_to(p.x);
        j.at("y").get_to(p.y);
        j.at("direction").get_to(p.direction);
    }
}

// CompPartInfo序列化
void to_json(json& j, const CompPartInfo& c)
{
    if (!c.blockType.empty())
    {
        j["BlockType"] = c.blockType;
    }

    j["Width"] = c.width;
    j["Height"] = c.height;
    j["Position"] = c.pos;
}

void from_json(const json& j, CompPartInfo& c)
{
    if (j.contains("BlockType"))
    {
        j.at("BlockType").get_to(c.blockType);
    }

    j.at("Width").get_to(c.width);
    j.at("Height").get_to(c.height);
    j.at("Position").get_to(c.pos);
}

// CompAndCanvasInfo序列化
void to_json(json& j, const CompAndCanvasInfo& c)
{
    j["Canvas"] = {{"Width", c.graphicSceneWidth}, {"Height", c.graphicSceneHeight}};
    j["Blocks"] = c.compPartInfos;

    if (!c.paths.empty())
    {
        j["Lines"] = json::array();
        for (const auto& path : c.paths)
        {
            j["Lines"].push_back(json{{"Line", path}});
        }
    }

    j["StartNode"] = c.startNode;
    j["EndNode"] = c.endNode;
}

void from_json(const json& j, CompAndCanvasInfo& c)
{
    j.at("Canvas").at("Width").get_to(c.graphicSceneWidth);
    j.at("Canvas").at("Height").get_to(c.graphicSceneHeight);
    j.at("Blocks").get_to(c.compPartInfos);

    if (j.contains("Lines"))
    {
        for (const auto& line : j.at("Lines"))
        {
            c.paths.push_back(line.at("Line"));
        }
    }

    j.at("StartNode").get_to(c.startNode);
    j.at("EndNode").get_to(c.endNode);
}

}  // namespace routenodes

int main(int argc, char* argv[])
{
    if (argc != 3)
    {
        std::cerr << "Usage: routenodescli in.json out.json" << std::endl;
        return 1;
    }

    std::string in_filename(argv[1]);
    std::string out_filename(argv[2]);

    std::ifstream ifs(in_filename);
    if (!ifs.is_open())
    {
        // 中文输出需要在UTF-8环境下才能正常显示
        std::cerr << "无法读取文件" << in_filename << std::endl;
        return 1;
    }

    json j;
    ifs >> j;
    routenodes::CompAndCanvasInfo canvas;
    j.get_to(canvas);

    bool ok = routenodes::validateCanvas(canvas);
    if (!ok)
    {
        // validateCanvas已经打印出错误信息
        return 1;
    }

    routenodes::Path path;
    routenodes::routeNodes(canvas, path);
    canvas.paths.push_back(path);

    std::ofstream ofs(out_filename);
    if (!ofs.is_open())
    {
        std::cerr << "无法写入文件" << out_filename << std::endl;
        return 1;
    }

    json out_j = canvas;
    ofs << out_j.dump(2);  // 2空格缩进
    return 0;
}
