bool rectOverlap(float l1, float r1, float t1, float b1, float l2, float r2, float t2, float b2, float margin)
{
    return !(r1 + margin < l2 || r2 + margin < l1 || b1 + margin < t2 || b2 + margin < t1);
}

// 两个模块的距离是否小于两者余量之和
bool compOverlap(const CompPartInfo& a, const CompPartInfo& b)
{
    return rectOverlap(a.pos.x, a.pos.x + a.width, a.pos.y, a.pos.y + a.height, b.pos.x, b.pos.x + b.width, b.pos.y,
                       b.pos.y + b.height, a.margin + b.margin);
