const float FloatMax = std::numeric_limits<float>::max();
const float FloatTol = std::numeric_limits<float>::epsilon() * 10;

const float BendPenalty = 100.0f;
const float PathOverlapPenalty = 2.0f;

// 两个浮点数是否在浮点误差内相等
bool isClose(const float a, const float b)
{
    return std::abs(a - b) < FloatTol;
}

// 三点是否共线
bool collinear(const CustomPoint& a, const CustomPoint& b, const CustomPoint& c)
{
    return isClose((b.x - a.x) * (c.y - b.y) - (b.y - a.y) * (c.x - b.x), 0.0f);
}

// 对浮点数组排序并去重
void sortAndDedup(std::vector<float>& v)
{
    std::sort(v.begin(), v.end());

    size_t count = 1;
    for (size_t i = 1; i < v.size(); ++i)
    {
        if (!isClose(v[i], v[count - 1]))
        {
            if (i != count)
            {
                v[count] = v[i];
            }

            ++count;
        }
    }

    v.resize(count);
}

