    {
        dwsg.rects.push_back({
            searchSorted(xs, comp.pos.x - comp.margin),
            searchSorted(xs, comp.pos.x + comp.width + comp.margin),
            searchSorted(ys, comp.pos.y - comp.margin),
            searchSorted(ys, comp.pos.y + comp.height + comp.margin),
