// 计算所求路径的核心代码

#include "routenodes.hpp"

#include <algorithm>
#include <queue>
#include <utility>
#include <vector>

namespace routenodes
{

// 拐点惩罚系数
const float BendPenalty = 100.0f;
// 路径重叠惩罚系数
const float PathOverlapPenalty = 2.0f;
// 路径居中奖励系数
const float PathMiddleReward = 1.0f / 3;

using MidLines = std::vector<std::pair<CustomPoint, CustomPoint>>;

void findMidLines(const CompAndCanvasInfo& wsg, MidLines& midLines)
{
    // 求所有极大空矩形
    std::vector<Rect> inRects;
    for (const auto& comp : wsg.compPartInfos)
    {
        inRects.push_back(Rect(comp));
    }

    const Rect canvas = {0.0f, wsg.graphicSceneWidth, 0.0f, wsg.graphicSceneHeight};
    std::vector<Rect> maxEmptyRects;
    findMaxEmptyRects(inRects, canvas, maxEmptyRects);

    for (const auto& rect : maxEmptyRects)
    {
        // 如果空矩形的左右不与画布边界重合，且左右距离大于两倍余量，则考虑竖直中线
        if (!isClose(rect.left, canvas.left) && !isClose(rect.right, canvas.right) &&
            rect.right - rect.left > 2.0f * DefaultMargin)
        {
            const float x = (rect.left + rect.right) / 2;
            midLines.push_back({{x, rect.top}, {x, rect.bottom}});
        }

        // 同理考虑水平中线
        if (!isClose(rect.top, canvas.top) && !isClose(rect.bottom, canvas.bottom) &&
            rect.bottom - rect.top > 2.0f * DefaultMargin)
        {
            const float y = (rect.top + rect.bottom) / 2;
            midLines.push_back({{rect.left, y}, {rect.right, y}});
        }
    }
}

// 统计出现在离散图上的所有画布坐标
void initXsYs(const CompAndCanvasInfo& wsg, const MidLines& midLines, std::vector<float>& xs, std::vector<float>& ys)
{
    // 模块扩大一圈余量后的x y坐标可能作为拐点
    // 允许新创建的点超出画布范围，否则可能出现画布中间完全被模块挡住，所求路径无法连通的情况
    for (const auto& comp : wsg.compPartInfos)
    {
        xs.push_back(comp.pos.x - comp.margin);
        xs.push_back(comp.pos.x + comp.width + comp.margin);
        ys.push_back(comp.pos.y - comp.margin);
        ys.push_back(comp.pos.y + comp.height + comp.margin);
    }

    // 已有路径的每个拐点扩大一圈余量后的x y坐标可能作为拐点
    for (const auto& path : wsg.paths)
    {
        for (size_t i = 1; i < path.size() - 1; ++i)
        {
            const auto& point = path[i];
            xs.push_back(point.x - DefaultMargin);
            xs.push_back(point.x);
            xs.push_back(point.x + DefaultMargin);
            ys.push_back(point.y - DefaultMargin);
            ys.push_back(point.y);
            ys.push_back(point.y + DefaultMargin);
        }
    }

    // 所求路径的起点与终点
    xs.push_back(wsg.startNode.x);
    ys.push_back(wsg.startNode.y);
    xs.push_back(wsg.endNode.x);
    ys.push_back(wsg.endNode.y);

    for (const auto& midLine : midLines)
    {
        xs.push_back(midLine.first.x);
        xs.push_back(midLine.first.y);
        xs.push_back(midLine.second.x);
        xs.push_back(midLine.second.y);
    }

    // 排序并去重
    sortAndDedup(xs);
    sortAndDedup(ys);
}

using DiscreteMidLines = std::vector<std::pair<DiscretePoint, DiscretePoint>>;

// 将画布坐标转换为离散图坐标
void initDiscreteCanvas(const CompAndCanvasInfo& wsg, const MidLines& midLines, const std::vector<float>& xs,
                        const std::vector<float>& ys, DiscreteCanvas& dwsg, DiscreteMidLines& dMidLines)
{
    for (const auto& comp : wsg.compPartInfos)
    {
        dwsg.rects.push_back({
            searchSorted(xs, comp.pos.x - comp.margin),
            searchSorted(xs, comp.pos.x + comp.width + comp.margin),
            searchSorted(ys, comp.pos.y - comp.margin),
            searchSorted(ys, comp.pos.y + comp.height + comp.margin),
        });
    }

    for (const auto& path : wsg.paths)
    {
        DiscretePath dpath;
        for (const auto& point : path)
        {
            dpath.push_back(searchSortedPoint(xs, ys, point));
        }

        dwsg.paths.push_back(dpath);
    }

    dwsg.startNode = searchSortedPoint(xs, ys, wsg.startNode);
    dwsg.endNode = searchSortedPoint(xs, ys, wsg.endNode);
    dwsg.startDirection = wsg.startNode.direction;
    dwsg.endDirection = wsg.endNode.direction;

    for (const auto& midLine : midLines)
    {
        dMidLines.push_back({searchSortedPoint(xs, ys, midLine.first), searchSortedPoint(xs, ys, midLine.second)});
    }
}

using FloatMat = std::vector<std::vector<float>>;

// 计算离散图所有边的权重
// hWeights[i][j] = 离散图上的节点(xs[i], ys[j])与(xs[i + 1], ys[j])之间的权重
// vWeights[i][j] = 离散图上的节点(xs[i], ys[j])与(xs[i], ys[j + 1])之间的权重
void initWeights(const std::vector<float>& xs, const std::vector<float>& ys, const DiscreteCanvas& dwsg,
                 const DiscreteMidLines& dMidLines, FloatMat& hWeights, FloatMat& vWeights)
{
    // 首先将权重设为画布上的距离
    for (size_t i = 0; i < xs.size() - 1; ++i)
    {
        const float d = xs[i + 1] - xs[i];
        for (size_t j = 0; j < ys.size(); ++j)
        {
            hWeights[i][j] = d;
        }
    }

    for (size_t j = 0; j < ys.size() - 1; ++j)
    {
        const float d = ys[j + 1] - ys[j];
        for (size_t i = 0; i < xs.size(); ++i)
        {
            vWeights[i][j] = d;
        }
    }

    // 禁止路径经过离散矩形内部
    // 由于离散矩形是原先的矩形扩大一圈余量得到的，允许路径与离散矩形的边缘重合
    for (const auto& rect : dwsg.rects)
    {
        for (size_t i = rect.left; i < rect.right; ++i)
        {
            for (size_t j = rect.top + 1; j < rect.bottom; ++j)
            {
                hWeights[i][j] = FloatMax;
            }
        }

        for (size_t i = rect.left + 1; i < rect.right; ++i)
        {
            for (size_t j = rect.top; j < rect.bottom; ++j)
            {
                vWeights[i][j] = FloatMax;
            }
        }
    }

    // 对每条已有路径，根据路径重叠惩罚系数增大权重
    // 若已有多条路径重叠，则将惩罚系数再次相乘
    for (const auto& path : dwsg.paths)
    {
        for (size_t k = 0; k < path.size() - 1; ++k)
        {
            const auto& point = path[k];
            const auto& next = path[k + 1];
            if (point.y == next.y)  // 水平
            {
                const size_t begin = std::min(point.x, next.x);
                const size_t end = std::max(point.x, next.x);
                for (size_t i = begin; i < end; ++i)
                {
                    hWeights[i][point.y] *= PathOverlapPenalty;
                }
            }
            else  // 竖直
            {
                const size_t begin = std::min(point.y, next.y);
                const size_t end = std::max(point.y, next.y);
                for (size_t j = begin; j < end; ++j)
                {
                    vWeights[point.x][j] *= PathOverlapPenalty;
                }
            }
        }
    }

    // 对每条中线，根据路径居中奖励系数减小权重
    for (const auto& midLine : dMidLines)
    {
        if (midLine.first.y == midLine.second.y)  // 水平
        {
            for (size_t i = midLine.first.x; i < midLine.second.x; ++i)
            {
                hWeights[i][midLine.first.y] *= PathMiddleReward;
            }
        }
        else  // 竖直
        {
            for (size_t j = midLine.first.y; j < midLine.second.y; ++j)
            {
                vWeights[midLine.first.x][j] *= PathMiddleReward;
            }
        }
    }

    // 由于离散矩形是原先的矩形扩大一圈余量得到的，所求路径的起点与终点在离散矩形内部，现在把它们重新连接到离散矩形边缘
    // 起点的方向指向模块外
    switch (dwsg.startDirection)
    {
        case Direction::North:
            vWeights[dwsg.startNode.x][dwsg.startNode.y - 1] = ys[dwsg.startNode.y] - ys[dwsg.startNode.y - 1];
            break;
        case Direction::South:
            vWeights[dwsg.startNode.x][dwsg.startNode.y] = ys[dwsg.startNode.y + 1] - ys[dwsg.startNode.y];
            break;
        case Direction::West:
            hWeights[dwsg.startNode.x - 1][dwsg.startNode.y] = xs[dwsg.startNode.x] - xs[dwsg.startNode.x - 1];
            break;
        case Direction::East:
            hWeights[dwsg.startNode.x][dwsg.startNode.y] = xs[dwsg.startNode.x + 1] - xs[dwsg.startNode.x];
            break;
        default:
            break;
    }

    // 终点的方向指向模块内
    switch (dwsg.endDirection)
    {
        case Direction::North:
            vWeights[dwsg.endNode.x][dwsg.endNode.y] = ys[dwsg.endNode.y + 1] - ys[dwsg.endNode.y];
            break;
        case Direction::South:
            vWeights[dwsg.endNode.x][dwsg.endNode.y - 1] = ys[dwsg.endNode.y] - ys[dwsg.endNode.y - 1];
            break;
        case Direction::West:
            hWeights[dwsg.endNode.x][dwsg.endNode.y] = xs[dwsg.endNode.x + 1] - xs[dwsg.endNode.x];
            break;
        case Direction::East:
            hWeights[dwsg.endNode.x - 1][dwsg.endNode.y] = xs[dwsg.endNode.x] - xs[dwsg.endNode.x - 1];
            break;
        default:
            break;
    }
}

// 离散图的数据结构
// graph[u][k] = {v, weight, isHorizontal}
// k是从节点u到v的边（在从节点u出发的所有边中的编号），weight是这条边的权重，isHorizontal记录这条边是否为水平
struct GraphEdge
{
    size_t nodeIdx;
    float weight;
    bool isHorizontal;

    // 在优先队列中比较顺序时，只比较权重
    bool operator>(const GraphEdge& other) const
    {
        return weight > other.weight;
    }
};

using Graph = std::vector<std::vector<GraphEdge>>;

// 生成离散图，每个节点到上下左右各有一条边，除非被模块挡住
void initGraph(const FloatMat& hWeights, const FloatMat& vWeights, Graph& graph)
{
    const size_t xSize = vWeights.size();
    const size_t ySize = hWeights[0].size();

    // 将离散图上的二维坐标转换为节点编号
    const auto idx = [ySize](const size_t i, const size_t j) { return i * ySize + j; };

    for (size_t i = 0; i < xSize - 1; ++i)
    {
        for (size_t j = 0; j < ySize; ++j)
        {
            if (hWeights[i][j] != FloatMax)
            {
                graph[idx(i, j)].push_back({idx(i + 1, j), hWeights[i][j], true});
                graph[idx(i + 1, j)].push_back({idx(i, j), hWeights[i][j], true});
            }
        }
    }

    for (size_t i = 0; i < xSize; ++i)
    {
        for (size_t j = 0; j < ySize - 1; ++j)
        {
            if (vWeights[i][j] != FloatMax)
            {
                graph[idx(i, j)].push_back({idx(i, j + 1), vWeights[i][j], false});
                graph[idx(i, j + 1)].push_back({idx(i, j), vWeights[i][j], false});
            }
        }
    }
}

// 用Dijkstra算法求最短路径
void findShortestPath(const Graph& graph, const size_t startIdx, const bool startIsHorizontal, const size_t endIdx,
                      const bool endIsHorizontal, std::vector<size_t>& outNodeIdxs)
{
    const size_t numNodes = graph.size();
    std::vector<std::vector<float>> dist(numNodes, std::vector<float>(2, FloatMax));
    std::vector<std::vector<std::pair<size_t, bool>>> parent(
        numNodes, std::vector<std::pair<size_t, bool>>(2, {numNodes, false}));
    std::priority_queue<GraphEdge, std::vector<GraphEdge>, std::greater<GraphEdge>> pq;

    dist[startIdx][startIsHorizontal] = 0.0f;
    pq.push({startIdx, 0.0f, startIsHorizontal});
    while (!pq.empty())
    {
        const GraphEdge curr = pq.top();
        pq.pop();

        const size_t u = curr.nodeIdx;
        if (u == endIdx && curr.isHorizontal == endIsHorizontal)
        {
            break;
        }

        if (curr.weight > dist[u][curr.isHorizontal])
        {
            continue;
        }

        for (const auto& next : graph[u])
        {
            const size_t v = next.nodeIdx;
            float weight = next.weight;
            if (curr.isHorizontal != next.isHorizontal)
            {
                weight += BendPenalty;
            }

            const float nextDist = dist[u][curr.isHorizontal] + weight;
            if (nextDist < dist[v][next.isHorizontal])
            {
                dist[v][next.isHorizontal] = nextDist;
                parent[v][next.isHorizontal] = {u, curr.isHorizontal};
                pq.push({v, nextDist, next.isHorizontal});
            }
        }
    }

    if (dist[endIdx][endIsHorizontal] != FloatMax)
    {
        size_t v = endIdx;
        bool h = endIsHorizontal;
        while (v != numNodes)
        {
            outNodeIdxs.push_back(v);
            const std::pair<size_t, bool> p = parent[v][h];
            v = p.first;
            h = p.second;
        }
    }

    // 以上输出的节点顺序是从终点到起点，现在将其反转为从起点到终点
    std::reverse(outNodeIdxs.begin(), outNodeIdxs.end());
}

// 去除共线的点
void removeCollinear(Path& path)
{
    for (size_t i = 1; i < path.size() - 1;)
    {
        if (collinear(path[i - 1], path[i], path[i + 1]))
        {
            path.erase(path.begin() + i);
        }
        else
        {
            ++i;
        }
    }
}

// 计算所求路径
void routeNodes(const CompAndCanvasInfo& wsg, Path& path)
{
    // 求所有中线
    MidLines midLines;
    findMidLines(wsg, midLines);

    // 统计出现在离散图上的所有画布坐标
    std::vector<float> xs, ys;
    initXsYs(wsg, midLines, xs, ys);

    // 将画布坐标转换为离散图坐标
    DiscreteCanvas dwsg;
    DiscreteMidLines dMidLines;
    initDiscreteCanvas(wsg, midLines, xs, ys, dwsg, dMidLines);

    // 计算离散图所有边的权重
    FloatMat hWeights(xs.size() - 1, std::vector<float>(ys.size()));
    FloatMat vWeights(xs.size(), std::vector<float>(ys.size() - 1));
    initWeights(xs, ys, dwsg, dMidLines, hWeights, vWeights);

    // 生成离散图
    Graph graph(xs.size() * ys.size());
    initGraph(hWeights, vWeights, graph);

    // 将离散图上的二维坐标转换为节点编号
    const size_t ySize = ys.size();
    const auto idx = [ySize](const size_t i, const size_t j) { return i * ySize + j; };

    // 求最短路径
    const size_t startIdx = idx(dwsg.startNode.x, dwsg.startNode.y);
    const size_t endIdx = idx(dwsg.endNode.x, dwsg.endNode.y);
    const bool startIsHorizontal = (dwsg.startDirection == Direction::West || dwsg.startDirection == Direction::East);
